import {
  createTopologySceneConfig,
  TOPOLOGY_CAMERA_BASE,
  TOPOLOGY_MINIMAP_BASE,
  TOPOLOGY_SCENE_BASE,
  TOPOLOGY_SIGNAL_BASE,
  type TopologyCameraConfig,
  type TopologyMiniMapConfig,
  type TopologyPageConfig,
  type TopologySceneConfig,
  type TopologySignalConfig,
} from "../topology/sceneConfig.ts";

export interface TopologyScenePresetOptions
  extends Omit<TopologySceneConfig, "viewportFit" | "connectorRouting"> {
  viewportFit?: boolean;
  connectorRouting?: TopologySceneConfig["connectorRouting"];
}

export interface TopologyPagePresetOptions {
  scene?: TopologyScenePresetOptions;
  camera?: Partial<TopologyCameraConfig>;
  signal?: Partial<TopologySignalConfig>;
  minimap?: Partial<TopologyMiniMapConfig>;
}

export interface TopologyPresetCatalogEntry {
  id: string;
  label: string;
  summary: string;
  role:
    | "intro"
    | "main"
    | "timeline"
    | "dossier"
    | "incident"
    | "architecture"
    | "knowledge"
    | "infrastructure"
    | "delivery";
  transition?: {
    entersFrom?: string;
    handoffTo?: string;
    reversible?: boolean;
  };
}

export function createTopologyScenePreset(
  options: TopologyScenePresetOptions,
): TopologySceneConfig {
  return createTopologySceneConfig({
    ...TOPOLOGY_SCENE_BASE,
    ...options,
  });
}

export function createTopologyPagePreset(
  options: TopologyPagePresetOptions,
): TopologyPageConfig {
  return {
    scene: createTopologyScenePreset(options.scene ?? TOPOLOGY_SCENE_BASE),
    camera: {
      ...TOPOLOGY_CAMERA_BASE,
      ...options.camera,
    },
    signal: {
      ...TOPOLOGY_SIGNAL_BASE,
      ...options.signal,
    },
    minimap: {
      ...TOPOLOGY_MINIMAP_BASE,
      ...options.minimap,
    },
  };
}

