export const TOPOLOGY_PRESET_CATALOG_BY_ID = Object.fromEntries(
  TOPOLOGY_PRESET_CATALOG.map((preset) => [preset.id, preset]),
) as Record<string, TopologyPresetCatalogEntry>;

export function getTopologyPresetCatalogEntry(id: string) {
  return TOPOLOGY_PRESET_CATALOG_BY_ID[id];
}

